import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Table, Badge, Button, Modal, Form } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import { toast } from 'react-toastify';
import { bpmnAPI, logistikAPI, adminAPI } from '../../services/api'; // Import APIs

const LogistikDashboard = () => {
  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    approved: 0,
    rejected: 0,
    roomsAvailable: 0
  });
  const [recentRequests, setRecentRequests] = useState([]);
  const [rooms, setRooms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showApproveModal, setShowApproveModal] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [selectedRequest, setSelectedRequest] = useState(null);
  const [selectedRoomId, setSelectedRoomId] = useState('');
  const [rejectionReason, setRejectionReason] = useState('');
  const [adminNotes, setAdminNotes] = useState('');

  useEffect(() => {
    console.log('🔄 Component mounted, fetching data...');
    fetchDashboardData();
  }, []);

  useEffect(() => {
    console.log('📊 Stats updated:', stats);
  }, [stats]);

  useEffect(() => {
    console.log('📝 Recent requests updated:', recentRequests.length, 'items');
  }, [recentRequests]);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      
      console.log('🔄 Fetching logistik dashboard data...');
      
      // Use multiple fallback approaches for getting requests
      let requests = [];
      let roomsList = [];

      try {
        // Prioritas utama: gunakan Admin API untuk mendapatkan SEMUA requests
        console.log('🔍 Fetching all requests for history...');
        const requestsResponse = await adminAPI.getAllRequests();
        console.log('✅ Admin API success:', requestsResponse);
        const allRequests = Array.isArray(requestsResponse.data) ? requestsResponse.data : [];
        // Filter for room-related requests only (room dan both)
        requests = allRequests.filter(req => 
          req.request_type === 'room' || req.request_type === 'both'
        );
        console.log('✅ Got', requests.length, 'room-related requests from', allRequests.length, 'total requests');
        
      } catch (adminError) {
        console.log('⚠️ Admin API failed, trying BPMN API...');
        try {
          // Fallback ke BPMN API untuk validated requests saja
          const requestsResponse = await bpmnAPI.getValidatedRequestsForLogistik();
          
          // Handle different response structures
          if (requestsResponse.data && requestsResponse.data.success && requestsResponse.data.data) {
            requests = requestsResponse.data.data;
            console.log('✅ Got', requests.length, 'validated requests');
          } else if (Array.isArray(requestsResponse.data)) {
            requests = requestsResponse.data;
            console.log('✅ Got', requests.length, 'requests');
          } else {
            requests = [];
            console.log('⚠️ No requests found');
          }
        } catch (bpmnError) {
          console.log('⚠️ BPMN API failed, trying logistik API...');
          try {
            const requestsResponse = await logistikAPI.getRoomRequests();
            console.log('✅ Logistik API success:', requestsResponse);
            requests = Array.isArray(requestsResponse.data) ? requestsResponse.data : [];
          } catch (logistikError) {
            console.error('❌ All request APIs failed:', { adminError, bpmnError, logistikError });
            requests = [];
          }
        }
      }

      try {
        console.log('🏢 Fetching rooms...');
        const roomsRes = await logistikAPI.getRooms();
        
        // Handle different response structures for rooms
        if (roomsRes.data && roomsRes.data.success && roomsRes.data.data) {
          roomsList = roomsRes.data.data;
          console.log('✅ Got', roomsList.length, 'rooms');
        } else if (Array.isArray(roomsRes.data)) {
          roomsList = roomsRes.data;
          console.log('✅ Got', roomsList.length, 'rooms');
        } else {
          roomsList = [];
          console.log('⚠️ No rooms found');
        }
      } catch (roomError) {
        console.error('❌ Error fetching rooms:', roomError);
        roomsList = [];
      }

      console.log('📊 Final processed data:', {
        requests: requests.length,
        rooms: roomsList.length
      });

      // Filter requests yang relevan untuk logistik
      const logistikRequests = requests.filter(req => 
        req.request_type === 'room' || req.request_type === 'both'
      );

      // Hitung statistik
      const pendingRequests = logistikRequests.filter(req => 
        (req.room_status === 'pending' || req.status === 'pending')
      );
      
      const approvedRequests = logistikRequests.filter(req => 
        (req.room_status === 'approved' || req.status === 'approved')
      );
      const rejectedRequests = logistikRequests.filter(req => 
        (req.room_status === 'rejected' || req.status === 'rejected')
      );
      const availableRooms = roomsList.filter(r => r.is_active).length;
      
      console.log('📈 Dashboard stats:', {
        total: logistikRequests.length,
        pending: pendingRequests.length,
        approved: approvedRequests.length,
        rejected: rejectedRequests.length,
        rooms: availableRooms
      });

      const newStats = {
        total: logistikRequests.length,
        pending: pendingRequests.length,
        approved: approvedRequests.length,
        rejected: rejectedRequests.length,
        roomsAvailable: availableRooms
      };

      console.log('📊 Setting dashboard data...');
      setStats(newStats);
      
      // Urutkan berdasarkan tanggal terbaru dan tampilkan lebih banyak history
      const sortedRequests = logistikRequests.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
      setRecentRequests(sortedRequests.slice(0, 50)); // Tampilkan 50 request terbaru
      setRooms(roomsList.filter(r => r.is_active));
      
      console.log('✅ Dashboard loaded successfully');
      
    } catch (error) {
      console.error('❌ Error fetching dashboard data:', error);
      toast.error('Gagal memuat data dashboard: ' + (error.response?.data?.message || error.message));
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = (request) => {
    setSelectedRequest(request);
    setAdminNotes('');
    if (request.request_type === 'room' || request.request_type === 'both') {
      setShowApproveModal(true);
    } else {
      // Direct approve for zoom only (shouldn't happen in logistik, but for consistency)
      submitApprove(request.id, null);
    }
  };

  const handleReject = (request) => {
    setSelectedRequest(request);
    setShowRejectModal(true);
  };

  const handleDetail = (request) => {
    setSelectedRequest(request);
    setShowDetailModal(true);
  };

  const submitApprove = async (requestId, roomId) => {
    try {
      // Coba menggunakan BPMN API terlebih dahulu
      try {
        const data = {
          action: 'approve'
        };
        if (roomId) {
          data.room_id = roomId;
          data.notes = `Ruangan disetujui oleh logistik`;
        }
        
        // Tambahkan admin notes jika ada
        if (adminNotes.trim()) {
          data.admin_notes = adminNotes.trim();
        }
        
        await bpmnAPI.logistikApproveRoom(requestId, data);
        
        // Berikan pesan yang spesifik berdasarkan jenis request
        if (selectedRequest.request_type === 'room') {
          toast.success('✅ Ruangan berhasil disetujui dan request diselesaikan!');
        } else if (selectedRequest.request_type === 'both') {
          toast.success('✅ Ruangan disetujui, request diselesaikan sepenuhnya!');
        }
        
      } catch (bpmnError) {
        console.log('BPMN API not ready, using fallback...');
        // Fallback ke API lama
        const data = roomId ? { 
          room_id: roomId, 
          notes: 'Ruangan disetujui oleh logistik',
          admin_notes: adminNotes.trim() || undefined
        } : {
          admin_notes: adminNotes.trim() || undefined
        };
        await logistikAPI.approveRoomRequest(requestId, data);
        toast.success('Request berhasil disetujui!');
      }
      
      fetchDashboardData();
      setShowApproveModal(false);
      setSelectedRoomId('');
      setAdminNotes('');
    } catch (error) {
      console.error('Error approving request:', error);
      toast.error('Gagal menyetujui request');
    }
  };

  const submitReject = async () => {
    if (!rejectionReason.trim()) {
      toast.error('Alasan penolakan harus diisi');
      return;
    }

    try {
      // Coba menggunakan BPMN API terlebih dahulu  
      try {
        await bpmnAPI.logistikRejectRoom(selectedRequest.id, {
          action: 'reject',
          notes: rejectionReason
        });
        toast.success('✅ Request berhasil ditolak!');
        
      } catch (bpmnError) {
        console.log('BPMN API not ready, using fallback...');
        // Fallback ke API lama
        await logistikAPI.rejectRoomRequest(selectedRequest.id, { reason: rejectionReason });
        toast.success('Request berhasil ditolak!');
      }

      fetchDashboardData();
      setShowRejectModal(false);
      setRejectionReason('');
    } catch (error) {
      console.error('Error rejecting request:', error);
      toast.error('Gagal menolak request');
    }
  };

  const getStatusBadge = (request) => {
    const status = request.room_status || request.status;
    const variants = {
      pending: 'warning',
      approved: 'success',
      rejected: 'danger'
    };
    
    return <Badge bg={variants[status] || 'secondary'}>{status?.toUpperCase() || 'UNKNOWN'}</Badge>;
  };

  const getRequestTypeBadge = (type) => {
    const variants = {
      room: 'success',
      zoom: 'primary', 
      both: 'warning'
    };
    
    const labels = {
      room: 'Ruangan',
      zoom: 'Zoom',
      both: 'Ruangan + Zoom'
    };
    
    return <Badge bg={variants[type] || 'secondary'}>{labels[type] || type}</Badge>;
  };

  if (loading) {
    return (
      <Container fluid className="py-4">
        <div className="text-center">
          <div className="spinner-border" role="status">
            <span className="visually-hidden">Loading...</span>
          </div>
        </div>
      </Container>
    );
  }

  return (
    <Container fluid className="py-4">
      <Row className="mb-4">
        <Col>
          <h2 className="mb-0">
            <i className="fas fa-building me-2 text-success"></i>
            Dashboard Logistik
          </h2>
          <p className="text-muted">Kelola persetujuan ruangan untuk meeting</p>
        </Col>
        <Col xs="auto">
          <Button as={Link} to="/logistik/rooms" variant="outline-success">
            <i className="fas fa-cog me-2"></i>Kelola Ruangan
          </Button>
          <Button as={Link} to="/logistik/bookings" variant="success" className="ms-2">
            <i className="fas fa-list me-2"></i>Semua Booking Ruangan  
          </Button>
        </Col>
      </Row>

      {/* Stats Cards */}
      <Row className="mb-4">
        <Col md={3}>
          <Card className="text-center border-0 shadow-sm">
            <Card.Body>
              <div className="display-6 text-warning mb-2">
                <i className="fas fa-clock"></i>
              </div>
              <h3 className="mb-1">{stats.pending}</h3>
              <p className="text-muted mb-0">Pending</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center border-0 shadow-sm">
            <Card.Body>
              <div className="display-6 text-success mb-2">
                <i className="fas fa-check-circle"></i>
              </div>
              <h3 className="mb-1">{stats.approved}</h3>
              <p className="text-muted mb-0">Approved</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center border-0 shadow-sm">
            <Card.Body>
              <div className="display-6 text-danger mb-2">
                <i className="fas fa-times-circle"></i>
              </div>
              <h3 className="mb-1">{stats.rejected}</h3>
              <p className="text-muted mb-0">Rejected</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center border-0 shadow-sm">
            <Card.Body>
              <div className="display-6 text-info mb-2">
                <i className="fas fa-door-open"></i>
              </div>
              <h3 className="mb-1">{stats.roomsAvailable}</h3>
              <p className="text-muted mb-0">Ruangan Tersedia</p>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Recent Room Requests */}
      <Row>
        <Col>
          <Card className="shadow-sm">
            <Card.Header className="bg-success text-white d-flex justify-content-between align-items-center">
              <h5 className="mb-0">
                <i className="fas fa-history me-2"></i>
                History Request Ruangan
              </h5>
              <Badge bg="light" text="dark">
                {recentRequests.length} Total Request
              </Badge>
            </Card.Header>
            <Card.Body className="p-0">
              {recentRequests.length > 0 ? (
                <Table responsive className="mb-0">
                  <thead className="table-light">
                    <tr>
                      <th>User</th>
                      <th>Judul</th>
                      <th>Tanggal Acara</th>
                      <th>Waktu</th>
                      <th>Jenis</th>
                      <th>Kapasitas</th>
                      <th>Ruangan</th>
                      <th>Status</th>
                      <th>Dibuat</th>
                      <th>Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recentRequests.map((request) => (
                      <tr key={request.id}>
                        <td>
                          <div>
                            <strong>{request.user_name}</strong>
                            <br />
                            <small className="text-muted">{request.user_email}</small>
                          </div>
                        </td>
                        <td>
                          <strong>{request.title}</strong>
                          <br />
                          <small className="text-muted">{request.purpose}</small>
                        </td>
                        <td>{new Date(request.date).toLocaleDateString('id-ID')}</td>
                        <td>
                          {request.start_time} - {request.end_time}
                        </td>
                        <td>
                          {getRequestTypeBadge(request.request_type)}
                        </td>
                        <td>{request.capacity} orang</td>
                        <td>
                          {request.room_name ? (
                            <Badge bg="info">{request.room_name}</Badge>
                          ) : (
                            <Badge bg="secondary">Belum dialokasi</Badge>
                          )}
                        </td>
                        <td>{getStatusBadge(request)}</td>
                        <td>
                          <small className="text-muted">
                            {new Date(request.created_at).toLocaleDateString('id-ID')}
                            <br />
                            {new Date(request.created_at).toLocaleTimeString('id-ID', { 
                              hour: '2-digit', 
                              minute: '2-digit' 
                            })}
                          </small>
                        </td>
                        <td>
                          <div className="d-flex gap-1">
                            {/* Tombol Detail - selalu ada */}
                            <Button
                              variant="info"
                              size="sm"
                              onClick={() => handleDetail(request)}
                              title="Lihat Detail"
                            >
                              <i className="fas fa-eye"></i>
                            </Button>

                            {/* Tombol Approve/Reject hanya untuk status pending */}
                            {request.room_status === 'pending' && (
                              <>
                                {/* Logistik hanya bisa approve/reject request room dan both */}
                                {(request.request_type === 'room' || request.request_type === 'both') && (
                                  <>
                                    <Button
                                      variant="success"
                                      size="sm"
                                      onClick={() => handleApprove(request)}
                                      title="Approve Request"
                                    >
                                      <i className="fas fa-check"></i>
                                    </Button>
                                    <Button
                                      variant="danger"
                                      size="sm"
                                      onClick={() => handleReject(request)}
                                      title="Reject Request"
                                    >
                                      <i className="fas fa-times"></i>
                                    </Button>
                                  </>
                                )}
                                {/* Untuk request zoom-only, logistik tidak bisa approve */}
                                {request.request_type === 'zoom' && (
                                  <Badge bg="secondary">
                                    Hanya untuk Admin IT
                                  </Badge>
                                )}
                              </>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              ) : (
                <div className="text-center py-4">
                  <i className="fas fa-history fa-3x text-muted mb-3"></i>
                  <p className="text-muted">Tidak ada history request ruangan</p>
                  <small className="text-muted">Request ruangan dan zoom+ruangan akan muncul di sini</small>
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Detail Modal */}
      <Modal show={showDetailModal} onHide={() => setShowDetailModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>Detail Request Ruangan</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedRequest && (
            <div>
              <Row className="mb-3">
                <Col md={6}>
                  <strong>Judul Acara:</strong>
                  <p>{selectedRequest.title}</p>
                </Col>
                <Col md={6}>
                  <strong>Penyelenggara:</strong>
                  <p>
                    <strong>{selectedRequest.user_name}</strong>
                    <br />
                    <small className="text-muted">{selectedRequest.user_email}</small>
                  </p>
                </Col>
              </Row>

              <Row className="mb-3">
                <Col md={6}>
                  <strong>Tanggal Acara:</strong>
                  <p>{new Date(selectedRequest.date).toLocaleDateString('id-ID')}</p>
                </Col>
                <Col md={6}>
                  <strong>Waktu:</strong>
                  <p>{selectedRequest.start_time} - {selectedRequest.end_time}</p>
                </Col>
              </Row>

              <Row className="mb-3">
                <Col md={6}>
                  <strong>Jenis Request:</strong>
                  <p>
                    <Badge bg={
                      selectedRequest.request_type === 'room' ? 'success' :
                      selectedRequest.request_type === 'zoom' ? 'primary' : 'warning'
                    }>
                      {selectedRequest.request_type === 'room' ? 'Ruangan Saja' :
                       selectedRequest.request_type === 'zoom' ? 'Zoom Saja' : 'Ruangan + Zoom'}
                    </Badge>
                  </p>
                </Col>
                <Col md={6}>
                  <strong>Status:</strong>
                  <p>
                    <Badge bg={
                      (selectedRequest.room_status || selectedRequest.status) === 'approved' ? 'success' :
                      (selectedRequest.room_status || selectedRequest.status) === 'rejected' ? 'danger' : 'warning'
                    }>
                      {((selectedRequest.room_status || selectedRequest.status) === 'approved' ? 'Disetujui' :
                       (selectedRequest.room_status || selectedRequest.status) === 'rejected' ? 'Ditolak' : 'Menunggu').toUpperCase()}
                    </Badge>
                  </p>
                </Col>
              </Row>

              <Row className="mb-3">
                <Col md={6}>
                  <strong>Jumlah Peserta:</strong>
                  <p>{selectedRequest.capacity} orang</p>
                </Col>
                <Col md={6}>
                  <strong>Ruangan:</strong>
                  <p>
                    {selectedRequest.room_name ? (
                      <Badge bg="info">{selectedRequest.room_name}</Badge>
                    ) : (
                      <Badge bg="secondary">Belum dialokasi</Badge>
                    )}
                  </p>
                </Col>
              </Row>

              <Row className="mb-3">
                <Col md={6}>
                  <strong>Kontak PIC:</strong>
                  <p>{selectedRequest.pic_contact || 'Tidak ada kontak PIC'}</p>
                </Col>
                <Col md={6}>
                  <strong>Dibuat:</strong>
                  <p>{new Date(selectedRequest.created_at).toLocaleString('id-ID')}</p>
                </Col>
              </Row>

              <Row className="mb-3">
                <Col md={12}>
                  <strong>Tujuan/Deskripsi:</strong>
                  <p>{selectedRequest.purpose || selectedRequest.description || 'Tidak ada deskripsi'}</p>
                </Col>
              </Row>

              {/* Informasi Zoom jika request type adalah zoom atau both */}
              {(selectedRequest.request_type === 'zoom' || selectedRequest.request_type === 'both') && (
                <div className="mt-4">
                  <h6>Informasi Zoom</h6>
                  <hr />
                  
                  {/* Manual Zoom Info */}
                  {selectedRequest.zoom_link_manual && (
                    <div className="bg-light p-3 rounded mb-3">
                      <div className="d-flex justify-content-between align-items-center mb-2">
                        <h6 className="mb-0">Informasi Zoom Manual</h6>
                        <Badge bg="success">Manual</Badge>
                      </div>
                      <Row>
                        <Col md={12} className="mb-2">
                          <strong>Link Meeting:</strong>
                          <p className="mb-1">
                            <a href={selectedRequest.zoom_link_manual} target="_blank" rel="noopener noreferrer">
                              {selectedRequest.zoom_link_manual}
                            </a>
                          </p>
                        </Col>
                        {selectedRequest.zoom_meeting_id_manual && (
                          <Col md={6} className="mb-2">
                            <strong>Meeting ID:</strong>
                            <p className="mb-1">{selectedRequest.zoom_meeting_id_manual}</p>
                          </Col>
                        )}
                        {selectedRequest.zoom_passcode_manual && (
                          <Col md={6} className="mb-2">
                            <strong>Passcode:</strong>
                            <p className="mb-1">{selectedRequest.zoom_passcode_manual}</p>
                          </Col>
                        )}
                      </Row>
                    </div>
                  )}
                  
                  {/* Auto Zoom Info */}
                  {selectedRequest.zoom_link && !selectedRequest.zoom_link_manual && (
                    <div className="bg-light p-3 rounded mb-3">
                      <div className="d-flex justify-content-between align-items-center mb-2">
                        <h6 className="mb-0">Informasi Zoom Otomatis</h6>
                        <Badge bg="info">Auto</Badge>
                      </div>
                      <Row>
                        <Col md={12} className="mb-2">
                          <strong>Link Meeting:</strong>
                          <p className="mb-1">
                            <a href={selectedRequest.zoom_link} target="_blank" rel="noopener noreferrer">
                              {selectedRequest.zoom_link}
                            </a>
                          </p>
                        </Col>
                        {selectedRequest.zoom_meeting_id && (
                          <Col md={6} className="mb-2">
                            <strong>Meeting ID:</strong>
                            <p className="mb-1">{selectedRequest.zoom_meeting_id}</p>
                          </Col>
                        )}
                        {selectedRequest.zoom_passcode && (
                          <Col md={6} className="mb-2">
                            <strong>Passcode:</strong>
                            <p className="mb-1">{selectedRequest.zoom_passcode}</p>
                          </Col>
                        )}
                      </Row>
                    </div>
                  )}

                  {/* No Zoom Info */}
                  {!selectedRequest.zoom_link && !selectedRequest.zoom_link_manual && (
                    <div className="text-muted">
                      <p>Informasi Zoom belum tersedia</p>
                    </div>
                  )}
                </div>
              )}

              {/* Admin Notes */}
              {selectedRequest.admin_notes && (
                <div className="mt-4">
                  <h6>Catatan Admin</h6>
                  <hr />
                  <div className="bg-light p-3 rounded">
                    <p className="mb-0">{selectedRequest.admin_notes}</p>
                  </div>
                </div>
              )}

              {/* Rejection Reason */}
              {(selectedRequest.room_status === 'rejected' || selectedRequest.status === 'rejected') && selectedRequest.rejection_reason && (
                <div className="mt-4">
                  <h6>Alasan Penolakan</h6>
                  <hr />
                  <div className="bg-danger bg-opacity-10 p-3 rounded border border-danger border-opacity-25">
                    <p className="mb-0 text-danger">{selectedRequest.rejection_reason}</p>
                  </div>
                </div>
              )}
            </div>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowDetailModal(false)}>
            Tutup
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Approve Modal */}
      <Modal show={showApproveModal} onHide={() => setShowApproveModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>
            {selectedRequest?.request_type === 'room' ? 'Approve Room Request' :
             selectedRequest?.request_type === 'both' ? 'Approve Room (Final Step)' :
             'Approve Request'}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedRequest && (
            <>
              <div className="alert alert-info">
                <i className="fas fa-info-circle me-2"></i>
                <strong>Logistik Role:</strong> 
                {selectedRequest.request_type === 'room' && 
                  ' Anda akan meng-approve ruangan dan menyelesaikan request.'
                }
                {selectedRequest.request_type === 'both' && 
                  ' Zoom sudah disetujui Admin IT. Anda akan meng-approve ruangan dan menyelesaikan request sepenuhnya.'
                }
                {selectedRequest.request_type === 'zoom' && 
                  ' Request ini hanya untuk zoom, akan langsung diteruskan ke Admin IT.'
                }
              </div>
              
              <p>Detail request:</p>
              <ul>
                <li><strong>Judul:</strong> {selectedRequest.title}</li>
                <li><strong>User:</strong> {selectedRequest.user_email}</li>
                <li><strong>Tanggal:</strong> {new Date(selectedRequest.date).toLocaleDateString('id-ID')}</li>
                <li><strong>Waktu:</strong> {selectedRequest.start_time} - {selectedRequest.end_time}</li>
                <li><strong>Kapasitas:</strong> {selectedRequest.capacity} orang</li>
                <li><strong>Jenis:</strong> 
                  {selectedRequest.request_type === 'zoom' && <Badge bg="primary">Zoom Only</Badge>}
                  {selectedRequest.request_type === 'room' && <Badge bg="success">Room Only</Badge>}
                  {selectedRequest.request_type === 'both' && <Badge bg="warning">Zoom + Room</Badge>}
                </li>
              </ul>

              {(selectedRequest.request_type === 'room' || selectedRequest.request_type === 'both') && (
                <Form.Group className="mt-3">
                  <Form.Label>Pilih Ruangan:</Form.Label>
                  <Form.Select
                    value={selectedRoomId}
                    onChange={(e) => setSelectedRoomId(e.target.value)}
                    required
                  >
                    <option value="">-- Pilih Ruangan --</option>
                    {rooms.filter(r => r.capacity >= selectedRequest.capacity).map(room => (
                      <option key={room.id} value={room.id}>
                        {room.room_name} (Kapasitas: {room.capacity})
                      </option>
                    ))}
                  </Form.Select>
                </Form.Group>
              )}

              {/* Admin Notes Section */}
              <Form.Group className="mt-3">
                <Form.Label>📝 Catatan untuk User (Opsional):</Form.Label>
                <Form.Control
                  as="textarea"
                  rows={3}
                  value={adminNotes}
                  onChange={(e) => setAdminNotes(e.target.value)}
                  placeholder="Berikan catatan tambahan untuk user (opsional)..."
                />
                <Form.Text className="text-muted">
                  Catatan ini akan dilihat oleh user di detail booking mereka.
                </Form.Text>
              </Form.Group>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowApproveModal(false)}>
            Batal
          </Button>
          <Button 
            variant="success" 
            onClick={() => submitApprove(selectedRequest?.id, selectedRoomId || null)}
            disabled={
              (selectedRequest?.request_type === 'room' || selectedRequest?.request_type === 'both') 
              && !selectedRoomId
            }
          >
            <i className="fas fa-check me-2"></i>
            Approve
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Reject Modal */}
      <Modal show={showRejectModal} onHide={() => setShowRejectModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Reject Request</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedRequest && (
            <>
              <p>Anda akan menolak request berikut:</p>
              <ul>
                <li><strong>Judul:</strong> {selectedRequest.title}</li>
                <li><strong>User:</strong> {selectedRequest.user_email}</li>
                <li><strong>Tanggal:</strong> {new Date(selectedRequest.date).toLocaleDateString('id-ID')}</li>
              </ul>
              
              <Form.Group className="mt-3">
                <Form.Label>Alasan Penolakan <span className="text-danger">*</span></Form.Label>
                <Form.Control
                  as="textarea"
                  rows={3}
                  value={rejectionReason}
                  onChange={(e) => setRejectionReason(e.target.value)}
                  placeholder="Masukkan alasan penolakan..."
                  required
                />
              </Form.Group>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowRejectModal(false)}>
            Batal
          </Button>
          <Button 
            variant="danger" 
            onClick={submitReject}
            disabled={!rejectionReason.trim()}
          >
            <i className="fas fa-times me-2"></i>
            Reject
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
};

export default LogistikDashboard;
